<template>
  <div class="full-width q-py-sm" v-if="isFormBuilderMode">
    <div class="vertex-builder-placeholder">
      <q-icon name="mdi-table" size="24px" color="grey-6" class="q-mr-sm" />
      <span class="text-subtitle1 text-weight-medium text-grey-7">{{ $t('vertex_tables_panel') }}</span>
    </div>
  </div>
  <div class="q-py-sm full-width" v-else>
    <VertexLineItemTable
      :fieldName="fieldName"
      :isReadOnly="isReadOnly"
    />

    <q-card flat bordered class="vertex-verification-card q-mt-sm" v-if="verification">
      <q-card-section class="q-pa-sm">
