              <div class="vertex-compare-header">{{ $t('vendor_tax') }}</div>
              <div class="vertex-compare-body">
                <div class="vertex-compare-amount">${{ formatAmount(verification.charged_tax) }}</div>
                <div class="vertex-compare-percent">{{ formatPercent(verification.charged_tax, verification.sub_total) }}</div>
              </div>
            </div>
          </div>
          <div class="col-auto flex items-center">
            <q-icon name="arrow_forward" size="24px" color="grey-5" />
          </div>
          <div class="col">
            <div class="vertex-compare-card">
              <div class="vertex-compare-header">{{ $t('vertex_tax') }}</div>
              <div class="vertex-compare-body">
                <div class="vertex-compare-amount">${{ formatAmount(verification.total_tax) }}</div>
                <div class="vertex-compare-percent">{{ formatPercent(verification.total_tax, verification.sub_total) }}</div>
              </div>
            </div>
          </div>
          <div class="col">
            <div class="vertex-compare-card" :class="exceededThreshold ? 'vertex-compare-card--exceeded' : 'vertex-compare-card--within'">
              <div class="vertex-compare-header" :class="exceededThreshold ? 'vertex-compare-header--exceeded' : 'vertex-compare-header--within'">{{ $t('difference') }}</div>
              <div class="vertex-compare-body">
                <div class="vertex-compare-amount" :class="exceededThreshold ? 'text-negative' : 'text-positive'">
                  ${{ formatAmount(verification.variance) }}
                </div>
                <div v-if="exceededThreshold" class="vertex-exceeded-label">
                  <q-icon name="warning" size="14px" color="negative" class="q-mr-xs" />
                  {{ $t('exceeded_threshold') }}
                </div>
                <div v-else class="vertex-within-label">
                  <q-icon name="check_circle" size="14px" color="positive" class="q-mr-xs" />
                  {{ $t('within_threshold') }}
                </div>
              </div>
            </div>
          </div>
        </div>
        <!-- variance threshold gauge -->
        <div class="vertex-gauge q-mt-md" v-if="threshold > 0">
          <div class="vertex-gauge-legend">
            <span class="vertex-gauge-legend-item">
              <span class="vertex-gauge-legend-dot vertex-gauge-legend-dot--threshold"></span>
              {{ $t('threshold') }}: ${{ formatAmount(threshold) }}
            </span>
            <span class="vertex-gauge-legend-item">
              <span class="vertex-gauge-legend-dot vertex-gauge-legend-dot--variance"></span>
              {{ $t('variance') }}: ${{ formatAmount(verification.variance) }}
            </span>
          </div>
          <div class="vertex-gauge-track">
            <div class="vertex-gauge-fill" :style="{ width: variancePercent + '%' }"></div>
            <div class="vertex-gauge-threshold-marker" :style="{ left: thresholdPercent + '%' }"></div>
            <div v-if="exceededThreshold && verification.variance > threshold" class="vertex-gauge-warning-icon" :style="{ left: variancePercent + '%' }">
              <q-icon name="warning" size="18px" color="negative" />
            </div>
          </div>
          <div class="vertex-gauge-range">
            <span class="vertex-gauge-range-label">$0</span>
            <span class="vertex-gauge-range-label">${{ formatAmount(verification.charged_tax) }}</span>
          </div>

        </div>
      </q-card-section>
    </q-card>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { useFormBuilderStore, useDocumentStore } from 'src/store/main';
import VertexLineItemTable from 'src/formBuilder/form_elements/components/VertexTablesPanel/VertexLineItemTable.vue';

export default defineComponent({
  name: 'VertexPanel',
  components: {
    VertexLineItemTable,
  },
  props: {
    currentField: {
      type: Object,
      default: () => ({}),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      required: false,
    },
    itemIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: [
    'inputValueChanges',
    'updateModel',
    'inputClicked',
    'applyFuzzySearch',
    'markTableColumns',
    'itemAdded',
    'removeField',
  ],
  computed: {
    record() {
      return useDocumentStore().record;
    },
    isFormBuilderMode() {
      return useFormBuilderStore().isFormBuilderMode;
    },
    verification() {
      return this.record?.vertex_tax_verification || null;
    },
    exceededThreshold() {
      const variance = this.verification?.variance ?? 0;
      return variance > this.threshold;
    },
    threshold() {
      return Number(this.verification?.threshold) || 0;
    },
    thresholdPercent() {
      const chargedTax = this.verification?.charged_tax ?? 0;
      if (chargedTax === 0) return 100;
      return Math.min((this.threshold / chargedTax) * 100, 100);
    },
    variancePercent() {
      const variance = this.verification?.variance ?? 0;
      const chargedTax = this.verification?.charged_tax ?? 0;
      if (chargedTax === 0) return 0;
      return Math.min((variance / chargedTax) * 100, 100);
    },
  },
  methods: {
    formatAmount(value: number | null | undefined): string {
      if (value == null) return '0.00';
      return Number(value).toFixed(2);
    },
    formatPercent(tax: number | null | undefined, subTotal: number | null | undefined): string {
      if (tax == null || subTotal == null || subTotal === 0) return '0.00';
      return ((tax / subTotal) * 100).toFixed(2) + '%';
    },
  },
});
</script>

