<template>
  <div class="q-py-sm full-width">
    <q-markup-table class="full-width text-uppercase sticky-header table-height" v-if="tableRows.length > 0">
      <thead>
        <tr class="highlighted-back">
          <th v-for="column in tableColumns" :key="column.name" class="text-left">
            {{ column.label }}
          </th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="(row, index) in tableRows" :key="index">
          <td v-for="column in tableColumns" :key="column.name" class="text-left">
            {{ row[column.name] }}
          </td>
        </tr>
      </tbody>
    </q-markup-table>
    <q-markup-table class="full-width" v-else>
      <thead>
        <tr class="highlighted-back">
          <th>{{ $t('no_data_available') }}</th>
        </tr>
      </thead>
    </q-markup-table>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocumentStore } from 'src/store/main';

export default defineComponent({
  name: 'VertexLineItemTable',
  props: {
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      tableColumns: [
        {
          name: 'line_number',
          field: 'line_number',
          align: 'left',
          label: this.$t('position'),
          sortable: true,
        },
        {
          name: 'description',
          field: 'description',
          align: 'left',
          label: this.$t('description'),
          sortable: true,
        },
        {
          name: 'item_id',
          field: 'item_id',
          align: 'left',
          label: this.$t('item_number'),
          sortable: true,
        },
        {
          name: 'tax_rate',
          field: 'tax_rate',
          align: 'left',
          label: this.$t('vertex_tax_rate'),
          sortable: true,
        },
        {
          name: 'tax_amount',
          field: 'tax_amount',
          align: 'left',
          label: this.$t('vertex_tax_amount'),
          sortable: true,
        },
      ] as any[],
      tableRows: [] as any[],
    };
  },
  mounted() {
    this.prepareTableData();
  },
  methods: {
    prepareTableData() {
      const docStore = useDocumentStore();
      const record = docStore.record;

      if (!record?.po_multi_matched || record.po_multi_matched.length === 0) {
        return;
      }

      this.tableRows = [];

      for (const data of record.po_multi_matched) {
        if (data.sub_lines) {
          // Single table line matched with multiple PO lines
          for (const subLine of data.sub_lines) {
            // Propagate parent-level item_id if missing in sub_line
            const rowData = { ...subLine };
            if (!rowData.item_id && data.item_id) {
              rowData.item_id = data.item_id;
            }
            this.addTableRow(rowData);
          }
        } else {
          // Single match or multiple table lines matched with single PO line
          this.addTableRow(data);
        }
      }
    },
    addTableRow(item: any) {
      this.tableRows.push({
        item_id: item.item_id || '',
        line_number: item.line_number || '',
        description: item.description || '',
        tax_rate: item.vertex?.tax_rate != null ? (Number(item.vertex.tax_rate) * 100).toFixed(2) + '%' : '',
        tax_amount: item.vertex?.tax_amount ?? '',
      });
    },
  },
});
</script>
